// Parity corpus — one representative step per route in the v1.1.0 contract
// (173 routes) plus the v2-only routes (P3 GraphQL/webhooks, P4
// CPT/taxonomy/plugins/profile/login-branding/change-password, P6
// extensions, P7 social, P8 WooCommerce, P9 school, P10 SEO depth,
// P11 Visual Builder, P12 Multisite),
// guard-matrix checks, and public-page checks. Total: 482 steps (200 v2-only).
//
// Step shape:
//   id, group, method, path ({{var}} resolved per-worker from captures),
//   auth: 'admin' | 'editor' | 'subscriber' | 'anon' | 'cart' | 'none'
//   body: JSON body | form: urlencoded | multipart: [{name,value} | {name,filename,type,file}]
//   capture: { var: 'data.id' } (JSON path on the response body)
//   captureCookie: 'admin' — store the Set-Cookie value into that auth slot
//   poll: { path: 'data.status', equals: 'done', timeoutMs } — re-fire the
//         step until the JSON path equals the value (async jobs)
//   expect: HTTP status both workers should return (a step where both match
//         each other but miss `expect` is flagged MATCH-BUT-UNEXPECTED)
//   compare: 'json' (default) | 'text' | 'status-only' | 'bytes-hash'
//   normalizeVersion: true — normalise semver strings (health version,
//         theme versions: v1 1.1.0/0.6.0 vs v2 2.0.0-dev/0.7.0, known diff #1/#3)
//   knownDiff: '<key>' — a diff on this step is documented in
//         known-diffs.json, not unexplained
//   v2only: true — run against v2 only (no v1 counterpart exists)
//
// Ordering rules (do not reorder casually):
//   - bad logins happen ONLY in the final lockout group (5-in-15-min window)
//   - destructive steps (deletes, revoke-all, restore, lockout) run late
//   - theme activation is undone inside its own group (default re-activated)
//   - TOTP enable/disable is self-contained (re-login after disable)

